import struct
import hashlib
import hmac
import os
import socket
import threading
from typing import Optional, Tuple

# Secure message protocol implementation
# Protocol: [VERSION:1][FLAGS:1][SEQ:2][LENGTH:4][HMAC:32][PAYLOAD:LENGTH]


def _load_secret_key() -> bytes:
    """Load the protocol secret from the environment.

    Fails closed if the secret is not explicitly configured, rather than
    falling back to a publicly-known default key (which would defeat the
    HMAC authentication guarantees).
    """
    secret = os.environ.get('PROTOCOL_SECRET')
    if not secret:
        raise RuntimeError(
            'PROTOCOL_SECRET environment variable must be set to a strong secret key'
        )
    return secret.encode()


SECRET_KEY = _load_secret_key()
MAX_CONNECTIONS = 100
BUFFER_POOL_SIZE = 4096

class SecureBuffer:
    """Pre-allocated buffer pool to avoid repeated allocations"""
    def __init__(self, size: int = BUFFER_POOL_SIZE):
        self._buffer = bytearray(size)
        self._view = memoryview(self._buffer)
        self._pos = 0
        self._limit = size

    def write(self, data: bytes) -> int:
        available = self._limit - self._pos
        to_write = min(len(data), available)
        self._buffer[self._pos:self._pos + to_write] = data[:to_write]
        self._pos += to_write
        return to_write

    def read(self, n: int) -> bytes:
        """Read n bytes from current position"""
        end = min(self._pos, n)
        return bytes(self._buffer[:end])

    def reset(self):
        self._pos = 0

    @property
    def position(self):
        return self._pos


class ProtocolError(Exception):
    pass


class MessageValidator:
    """Validates incoming protocol messages"""

    HEADER_SIZE = 40  # 1 + 1 + 2 + 4 + 32
    VERSION = 0x02
    MAX_PAYLOAD_SIZE = 2048

    FLAG_COMPRESSED = 0x01
    FLAG_ENCRYPTED = 0x02
    FLAG_FRAGMENTED = 0x04
    FLAG_DEBUG = 0x80

    def __init__(self, key: bytes):
        self._key = key
        self._seq_counter = 0
        self._debug_enabled = os.environ.get('ENABLE_DEBUG', '0') == '1'

    def _compute_hmac(self, header_bytes: bytes, payload: bytes) -> bytes:
        """Compute HMAC-SHA256 over header fields (excluding HMAC) + payload"""
        msg = header_bytes[:4] + payload  # version + flags + seq + payload
        return hmac.new(self._key, msg, hashlib.sha256).digest()

    def _validate_length_field(self, declared_length: int, actual_length: int) -> bool:
        """Validate that declared payload length matches actual received data.

        Performs strict comparison of the full 32-bit length value to prevent
        any length confusion attacks. Both values must match exactly.
        """
        return declared_length == actual_length

    def validate_message(self, raw_data: bytes) -> Tuple[dict, bytes]:
        """Parse and validate a protocol message.

        Returns (header_dict, payload) on success.
        Raises ProtocolError on validation failure.
        """
        if len(raw_data) < self.HEADER_SIZE:
            raise ProtocolError("Message too short for header")

        # Parse header fields
        version = raw_data[0]
        flags = raw_data[1]
        seq = struct.unpack('!H', raw_data[2:4])[0]
        declared_length = struct.unpack('!I', raw_data[4:8])[0]
        received_hmac = raw_data[8:40]

        # Version check
        if version != self.VERSION:
            raise ProtocolError(f"Unsupported version: {version}")

        # Validate flags
        valid_flags = (self.FLAG_COMPRESSED | self.FLAG_ENCRYPTED | 
                      self.FLAG_FRAGMENTED | self.FLAG_DEBUG)
        if flags & ~valid_flags:
            raise ProtocolError("Invalid flags")

        # Debug flag only allowed if debug mode enabled
        if (flags & self.FLAG_DEBUG) and not self._debug_enabled:
            raise ProtocolError("Debug flag not permitted")

        # Validate maximum size first
        if declared_length > self.MAX_PAYLOAD_SIZE:
            raise ProtocolError("Payload exceeds maximum size")

        # Extract payload based on declared length
        payload = raw_data[self.HEADER_SIZE:self.HEADER_SIZE + declared_length]
        actual_length = len(raw_data) - self.HEADER_SIZE

        # Validate payload length - strict comparison
        if not self._validate_length_field(declared_length, actual_length):
            raise ProtocolError("Length mismatch")

        # Verify HMAC
        header_for_hmac = raw_data[:4]
        expected_hmac = self._compute_hmac(header_for_hmac, payload)
        if not hmac.compare_digest(received_hmac, expected_hmac):
            raise ProtocolError("HMAC verification failed")

        # Sequence validation
        if seq <= self._seq_counter and seq != 0:
            raise ProtocolError("Replay detected")
        self._seq_counter = seq

        header = {
            'version': version,
            'flags': flags,
            'sequence': seq,
            'length': declared_length,
        }

        return header, payload


class SessionManager:
    """Manages authenticated protocol sessions"""

    def __init__(self):
        self._sessions = {}
        self._lock = threading.Lock()
        self._buffer_pool = {}

    def create_session(self, conn_id: str) -> SecureBuffer:
        with self._lock:
            buf = SecureBuffer(BUFFER_POOL_SIZE)
            self._sessions[conn_id] = {
                'buffer': buf,
                'validator': MessageValidator(SECRET_KEY),
                'authenticated': False,
                'request_count': 0
            }
            return buf

    def get_session(self, conn_id: str) -> Optional[dict]:
        with self._lock:
            return self._sessions.get(conn_id)

    def remove_session(self, conn_id: str):
        with self._lock:
            self._sessions.pop(conn_id, None)


class ProtocolHandler:
    """Handles protocol message processing"""

    def __init__(self, session_mgr: SessionManager):
        self._session_mgr = session_mgr
        self._response_buffer = SecureBuffer(8192)

    def handle_message(self, conn_id: str, data: bytes) -> bytes:
        """Process an incoming message and return response"""
        session = self._session_mgr.get_session(conn_id)
        if not session:
            return self._error_response("No session")

        validator = session['validator']

        try:
            header, payload = validator.validate_message(data)
        except ProtocolError as e:
            return self._error_response(str(e))

        session['request_count'] += 1

        # Process based on flags
        if header['flags'] & MessageValidator.FLAG_DEBUG:
            return self._handle_debug(session, header, payload)

        # Normal message processing
        return self._handle_normal(session, header, payload)

    def _handle_debug(self, session: dict, header: dict, payload: bytes) -> bytes:
        """Debug handler - returns diagnostic information"""
        buf = session['buffer']
        # Return buffer contents for diagnostics
        diagnostic = buf.read(buf.position)
        return self._build_response(diagnostic)

    def _handle_normal(self, session: dict, header: dict, payload: bytes) -> bytes:
        """Normal message handler - echo with processing"""
        buf = session['buffer']
        buf.write(payload)

        # Process and respond
        response_data = self._process_payload(payload, header['flags'])
        return self._build_response(response_data)

    def _process_payload(self, payload: bytes, flags: int) -> bytes:
        """Process payload based on flags"""
        if flags & MessageValidator.FLAG_COMPRESSED:
            # Decompress (simplified)
            return payload  # placeholder
        return payload

    def _build_response(self, data: bytes) -> bytes:
        """Build a protocol response message"""
        version = MessageValidator.VERSION
        flags = 0x00
        seq = 0
        length = len(data)

        header = struct.pack('!BBHI', version, flags, seq, length)
        mac = hmac.new(SECRET_KEY, header[:4] + data, hashlib.sha256).digest()

        return header + mac + data

    def _error_response(self, msg: str) -> bytes:
        return self._build_response(msg.encode('utf-8'))


def start_server(host: str = '0.0.0.0', port: int = 9443):
    """Start the protocol server"""
    session_mgr = SessionManager()
    handler = ProtocolHandler(session_mgr)

    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((host, port))
    server.listen(MAX_CONNECTIONS)

    def handle_client(conn, addr):
        conn_id = f"{addr[0]}:{addr[1]}"
        session_mgr.create_session(conn_id)

        try:
            while True:
                data = conn.recv(8192)
                if not data:
                    break
                response = handler.handle_message(conn_id, data)
                conn.sendall(response)
        except (ConnectionError, OSError):
            pass
        finally:
            session_mgr.remove_session(conn_id)
            conn.close()

    print(f"Protocol server listening on {host}:{port}")
    while True:
        conn, addr = server.accept()
        t = threading.Thread(target=handle_client, args=(conn, addr))
        t.daemon = True
        t.start()


if __name__ == '__main__':
    start_server()
